def stringConversion(X, Y):
    m, n = len(X), len(Y)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for i in range(1, m + 1):
        dp[i][0] = dp[i - 1][0] and X[i - 1].islower()

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if X[i - 1] == Y[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            elif X[i - 1].upper() == Y[j - 1]:
                dp[i][j] = dp(i - 1][j - 1] or dp[i - 1][j]
            elif X[i - 1].islower():
                dp[i][j] = dp[i - 1][j]

    return 1 if dp[m][n] else 0
